WHO = {'column': [('aprimcohum', 23752), ('mulgmeyeben', 23752), ('aprilfools', 23752), ('vatheyeben', 0), ('vathedccohum', 24008), ('unyatem', 24008), ('vathedccohum', 24008), ('mudoum', 24008)], 'manor': [('weitfeyeben', 0), ('qusnsol', 0), ('weitflldoum', 0), ('brideyeben', 0), ('aprimchaun', 26760), ('psiloccohum', 33608), ('aprimchaun', 0), ('weitflldoum', 37895)], 'tree': [('rocilsof', 0), ('einlsof', 0), ('einccldmolum', 29512), ('einlsof', 31176), ('einccldmolum', 0), ('einlsof', 34568), ('aprilsof', 35016), ('aprilfools', 35463)], 'bridge': [('rocieyeben', 24584), ('losensol', 24712), ('losensol', 25352), ('mudoum', 25928), ('alphafoldmicro', 26632), ('mudoum', 26760), ('mudoum', 0), ('aprilnor', 29512)], 'temple': [('solya', 24712), ('aprilsof', 0), ('psiloceyeben', 26760), ('aprimcohum', 26888), ('unyalldoum', 29128), ('solya', 0), ('aprilmhum', 34312), ('solya', 36167)], 'tower': [('solya', 0), ('vatheyeben', 28040), ('psiloceyeben', 28040), ('aprimeyeben', 28744), ('aprimclsof', 0), ('aprimvi', 31176), ('losensol', 0), ('rociensol', 37639)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW158(OracleReleaseRuntimeW156):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
